/* i18n runtime (hand-written). Dictionaries come from i18n.js, GENERATED by tools/build-i18n.js from
 * /workspace/carlsen/i18n/en.json (canonical English) and vi.json (Vance's). Loaded before data.js, logic.js and app.js.
 * t(key, vars, fallback): looks up the current language, then English, per key. Empty strings count as missing.
 *   Plurals: pass vars.n; the lookup tries "<key>.<category>" (Intl.PluralRules: one, other, ...) then "<key>.other".
 *   Placeholders: {name} in the string is replaced with vars.name (no string concatenation in the app).
 *   A key missing in English returns `fallback` if given (data-driven keys such as exercise names), else the key itself,
 *   and is recorded in I18N.missing so tests can fail on it. */
(function (root) {
  "use strict";
  const DICT = root.CARLSEN_I18N || { en: {}, vi: {}, pseudo: {} };
  const LANGS = ["en", "vi", "pseudo"];   // "pseudo" = test locale (en padded ~40% with Vietnamese diacritics); not offered in the UI
  const LOCALE = { en: "en-GB", vi: "vi-VN", pseudo: "en-GB" };
  const KEY = "carlsen2.lang";
  let lang = "en";
  try {
    const q = (root.location && /[?&]lang=([a-z]+)/.exec(root.location.search || "")) || null;
    const saved = root.localStorage && root.localStorage.getItem(KEY);
    const want = q ? q[1] : saved ? JSON.parse(saved) : "en";
    if (LANGS.includes(want)) lang = want;
  } catch (e) { /* storage blocked: stay on en */ }
  const missing = [];
  const has = (d, k) => d && typeof d[k] === "string" && d[k] !== "";
  const plurals = {};
  const cat = (l, n) => { try { return (plurals[l] = plurals[l] || new Intl.PluralRules(LOCALE[l] || l)).select(n); } catch (e) { return n === 1 ? "one" : "other"; } };
  function raw(key, vars) {
    const order = lang === "en" ? ["en"] : [lang, "en"];
    const plural = vars && typeof vars.n === "number";
    for (const l of order) {
      const d = DICT[l];
      if (plural) { const c = cat(l, vars.n); if (has(d, key + "." + c)) return d[key + "." + c]; if (has(d, key + ".other")) return d[key + ".other"]; }
      if (has(d, key)) return d[key];
    }
    return null;
  }
  const fill = (s, vars) => !vars ? s : s.replace(/\{(\w+)\}/g, (m, k) => (Object.prototype.hasOwnProperty.call(vars, k) && vars[k] != null ? String(vars[k]) : m));
  function t(key, vars, fallback) {
    const s = raw(key, vars);
    if (s != null) return fill(s, vars);
    if (fallback !== undefined) return fill(String(fallback), vars);
    if (!missing.includes(key)) missing.push(key);
    return key;
  }
  const exists = (key) => raw(key, null) != null || raw(key, { n: 2 }) != null;
  const locale = () => LOCALE[lang] || "en-GB";
  function list(items, type) {
    items = (items || []).map(String);
    try { return new Intl.ListFormat(locale(), { style: "long", type: type || "conjunction" }).format(items); }
    catch (e) { return items.length <= 1 ? items.join("") : items.slice(0, -1).join(", ") + (type === "disjunction" ? " or " : " and ") + items[items.length - 1]; }
  }
  const lower = (s) => String(s).toLocaleLowerCase(locale());
  const cap = (s) => (s = String(s || "")) && s.charAt(0).toLocaleUpperCase(locale()) + s.slice(1);
  // Muscles are stored by their English names ("Upper back"); the key is muscle.<exercises.json id with spaces as _>.
  const muscleId = (m) => String(m).toLowerCase().replace(/\s+/g, "_");
  const muscle = (m) => t("muscle." + muscleId(m), null, m);
  function setLang(l) { if (!LANGS.includes(l)) return; lang = l; try { root.localStorage.setItem(KEY, JSON.stringify(l)); } catch (e) {} }
  root.I18N = { t, exists, list, lower, cap, muscle, muscleId, setLang, locale, missing, langs: ["en", "vi"], get lang() { return lang; } };
})(typeof self !== "undefined" ? self : this);
